"""Generated by the NL to Flow Diagram Encoder Pipeline."""

corpus = ['the team won the match and scored many goals', 'the player scored a hat trick in the game', 'the championship match ended in a victory', 'new smartphone released with powerful processor and fast performance', 'software update improves device performance and battery life', 'AI model achieves breakthrough in image recognition', 'fresh ingredients used in this recipe', 'the chef prepares a delicious meal at the restaurant', 'the restaurant serves tasty dishes and great food']

stopwords = ['the', 'and', 'in', 'a', 'at', 'with', 'this', 'many']

def tokenise(text):
    words = text.lower().split()
    clean = []
    i = 0
    loop = True
    while loop:
        try:
            if (words[i] not in stopwords):
                clean.append(words[i])
            i = (i + 1)
        except Exception:
            loop = False
    return clean

word_freq = {}

co_occurrence = {}

doc_tokens = []

i = 0

loop = True

while loop:
    try:
        text = corpus[i]
        words = tokenise(text)
        doc_tokens.append(words)
        j = 0
        innerloop = True
        while innerloop:
            try:
                w = words[j]
                if (w not in word_freq):
                    word_freq[w] = 0
                word_freq[w] = (word_freq[w] + 1)
                j = (j + 1)
            except Exception:
                innerloop = False
        j = 0
        innerloop = True
        while innerloop:
            try:
                w1 = words[j]
                if (w1 not in co_occurrence):
                    co_occurrence[w1] = {}
                k = 0
                inner2 = True
                while inner2:
                    try:
                        w2 = words[k]
                        if (w1 != w2):
                            if (w2 not in co_occurrence[w1]):
                                co_occurrence[w1][w2] = 0
                            co_occurrence[w1][w2] = (co_occurrence[w1][w2] + 1)
                        k = (k + 1)
                    except Exception:
                        inner2 = False
                j = (j + 1)
            except Exception:
                innerloop = False
        i = (i + 1)
    except Exception:
        loop = False

items = []

for word_entry in word_freq.items():
    items.append(word_entry)

n = len(items)

i = 0

loop = True

while loop:
    if (i >= (n - 1)):
        loop = False
    else:
        j = 0
        innerloop = True
        while innerloop:
            if (j >= (n - 1)):
                innerloop = False
            else:
                if (items[j][1] < items[(j + 1)][1]):
                    temp = items[j]
                    items[j] = items[(j + 1)]
                    items[(j + 1)] = temp
                j = (j + 1)
        i = (i + 1)

TOP_K = 12

top_words = []

i = 0

loop = True

while loop:
    if ((i >= TOP_K) or (i >= len(items))):
        loop = False
    else:
        top_words.append(items[i][0])
        i = (i + 1)

topics = []

used = {}

i = 0

loop = True

while loop:
    try:
        w = top_words[i]
        if (w not in used):
            topic = [w]
            used[w] = True
            if (w in co_occurrence):
                pairs = []
                for cooccurrence_entry in co_occurrence[w].items():
                    pairs.append(cooccurrence_entry)
                m = len(pairs)
                a = 0
                sortloop = True
                while sortloop:
                    if (a >= (m - 1)):
                        sortloop = False
                    else:
                        b = 0
                        innersort = True
                        while innersort:
                            if (b >= (m - 1)):
                                innersort = False
                            else:
                                if (pairs[b][1] < pairs[(b + 1)][1]):
                                    temp = pairs[b]
                                    pairs[b] = pairs[(b + 1)]
                                    pairs[(b + 1)] = temp
                                b = (b + 1)
                        a = (a + 1)
                c = 0
                addloop = True
                while addloop:
                    try:
                        w2 = pairs[c][0]
                        if (w2 not in used):
                            topic.append(w2)
                            used[w2] = True
                        c = (c + 1)
                        if (c >= 2):
                            addloop = False
                    except Exception:
                        addloop = False
            topics.append(topic)
        i = (i + 1)
    except Exception:
        loop = False

label_words = {}

label_words['Sports'] = ['team', 'match', 'goal', 'player', 'score', 'victory', 'game']

label_words['Tech'] = ['processor', 'software', 'device', 'update', 'model', 'performance', 'smartphone']

label_words['Food'] = ['chef', 'meal', 'ingredients', 'recipe', 'restaurant', 'dishes', 'food']

def auto_label(topic):
    best_label = None
    best_score = (-1)
    labels = []
    for label_name in label_words.keys():
        labels.append(label_name)
    l_index = 0
    loop = True
    while loop:
        try:
            label = labels[l_index]
            score = 0
            t_index = 0
            innerloop = True
            while innerloop:
                try:
                    w = topic[t_index]
                    lw_index = 0
                    lw_loop = True
                    while lw_loop:
                        try:
                            if (w == label_words[label][lw_index]):
                                score = (score + 1)
                            lw_index = (lw_index + 1)
                        except Exception:
                            lw_loop = False
                    t_index = (t_index + 1)
                except Exception:
                    innerloop = False
            if (score > best_score):
                best_score = score
                best_label = label
            l_index = (l_index + 1)
        except Exception:
            loop = False
    return (best_label, best_score)

topic_labels = []

i = 0

loop = True

while loop:
    try:
        topic = topics[i]
        label_result = auto_label(topic)
        label = label_result[0]
        score = label_result[1]
        topic_labels.append(label)
        i = (i + 1)
    except Exception:
        loop = False

def classify(text):
    words = tokenise(text)
    best_topic = None
    best_label = None
    best_score = (-1)
    i = 0
    loop = True
    while loop:
        try:
            topic = topics[i]
            label = topic_labels[i]
            score = 0
            j = 0
            innerloop = True
            while innerloop:
                try:
                    if (words[j] in topic):
                        score = (score + 1)
                    j = (j + 1)
                except Exception:
                    innerloop = False
            if (score > best_score):
                best_score = score
                best_topic = topic
                best_label = label
            i = (i + 1)
        except Exception:
            loop = False
    return (best_label, best_topic, best_score)

print('Topics -> Category:\n')

